-- Admin-managed public About Us and Contact Us pages.
INSERT OR IGNORE INTO support_pages (slug, label, title, intro, contact_email, contact_phone, support_hours, support_cta_label, support_cta_url, sections, faqs, updated_at)
VALUES ('about', 'About Us', 'Built to make postgraduate medical preparation more focused.', 'TracePG brings high-yield practice, revision, and progress tracking into one calm study workspace for medical students and doctors preparing for postgraduate entrance exams.', '', '', '', 'Explore TracePG', '/', '[["Website operator","TracePG is operated by Yogesh Kumar Kashyap."],["Our approach","We believe consistent, deliberate practice beats last-minute cramming. TracePG helps you turn a large question bank into a repeatable daily workflow with focused tests, review, analytics, and revision reminders."],["What you can do here","Practise topic-wise questions, work through previous-year questions, review every answer, save notes, track weak areas, and return to the questions that need another look."],["Made for your preparation journey","Your study history and progress stay connected to your account so you can build momentum over time and make each practice session more useful than the last."]]', '[]', 0);

INSERT OR IGNORE INTO support_pages (slug, label, title, intro, contact_email, contact_phone, support_hours, support_cta_label, support_cta_url, sections, faqs, updated_at)
VALUES ('contact', 'Contact Us', 'We’re here to help you keep moving.', 'Have a question, found an issue, or want to share feedback? Reach out and the TracePG team will get back to you.', 'support@tracepg.com', '', 'Monday to Friday, 9:00 AM to 6:00 PM IST', 'Email us', 'mailto:support@tracepg.com', '[["Before you write","For account or payment questions, include the email address used for your TracePG account and any relevant transaction details. Please do not send passwords or other sensitive credentials."],["Feedback and suggestions","Tell us what would make your preparation workflow better. Product feedback, content corrections, and ideas for future features are welcome."]]', '[]', 0);
